begin;
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end $$;
create function pg_temp.expect_error(command text,expected text) returns void language plpgsql as $$declare actual text; begin begin execute command; exception when others then get stacked diagnostics actual=returned_sqlstate; end; if actual is distinct from expected then raise exception 'expected %, got %',expected,actual; end if; end $$;
insert into auth.users(id) values('61102000-0000-4000-8000-000000000001'),('61102000-0000-4000-8000-000000000002'),('61102000-0000-4000-8000-000000000003');
set local role authenticated;
set local request.jwt.claim.sub='61102000-0000-4000-8000-000000000001';
select public.community_send_message('61102000-0000-4000-8000-000000000002','history',gen_random_uuid());
select public.community_block_user('61102000-0000-4000-8000-000000000002');
select public.community_block_user('61102000-0000-4000-8000-000000000002');
select pg_temp.assert_true((select count(*)=1 from public.community_list_blocks()),'duplicate block idempotent');
select pg_temp.assert_true(public.community_has_block('61102000-0000-4000-8000-000000000002'),'own block visible');
select pg_temp.assert_true(jsonb_array_length(public.community_message_history('61102000-0000-4000-8000-000000000002'))=1,'history retained');
select pg_temp.expect_error($q$select public.community_block_user(auth.uid())$q$,'23514');
select pg_temp.expect_error($q$select public.community_send_message('61102000-0000-4000-8000-000000000002','blocked',gen_random_uuid())$q$,'42501');
set local request.jwt.claim.sub='61102000-0000-4000-8000-000000000002';
select pg_temp.expect_error($q$select public.community_send_message('61102000-0000-4000-8000-000000000001','blocked',gen_random_uuid())$q$,'42501');
select pg_temp.assert_true(not public.community_has_block('61102000-0000-4000-8000-000000000001'),'cannot inspect peer block');
select pg_temp.assert_true((select count(*)=0 from public.community_user_blocks),'RLS hides other blocks');
select pg_temp.expect_error($q$insert into public.community_user_blocks(blocker_id,blocked_id) values('61102000-0000-4000-8000-000000000001','61102000-0000-4000-8000-000000000003')$q$,'42501');
delete from public.community_user_blocks where blocker_id='61102000-0000-4000-8000-000000000001';
set local request.jwt.claim.sub='61102000-0000-4000-8000-000000000001';
select pg_temp.assert_true(public.community_has_block('61102000-0000-4000-8000-000000000002'),'peer cannot remove own block');
select public.community_unblock_user('61102000-0000-4000-8000-000000000002');
select pg_temp.assert_true(not public.community_has_block('61102000-0000-4000-8000-000000000002'),'unblock');
select public.community_send_message('61102000-0000-4000-8000-000000000002','unblocked',gen_random_uuid());
rollback;
